DROP PROCEDURE if exists update_in_loop;

DELIMITER $$
CREATE PROCEDURE update_in_loop()
BEGIN    DECLARE v_min_id BIGINT DEFAULT 0;
    DECLARE v_max_id BIGINT DEFAULT 0;
    DECLARE v_batch_size INT DEFAULT 100;
    DECLARE v_sleep_cnt INT DEFAULT 0;
    DECLARE v_sleep_after INT DEFAULT 5;
    DECLARE v_sleep_time INT DEFAULT 1;

    SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_payment`.`payment_order`;
    SELECT v_min_id, v_max_id, v_batch_size;

    WHILE v_min_id <= v_max_id DO            UPDATE `taxify_payment`.`payment_order` SET business_line = 'top_up' WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND business_line = 'topup';

            SET v_min_id = v_min_id + v_batch_size;

            SET v_sleep_cnt = v_sleep_cnt + 1;
            SELECT v_min_id, v_sleep_cnt, v_sleep_after;

            IF v_sleep_cnt > v_sleep_after THEN                SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
                SELECT SLEEP(v_sleep_time);
                SET v_sleep_cnt = 0;
            END IF;

        END WHILE;

END;
$$
DELIMITER ;

CALL update_in_loop();
DROP PROCEDURE if exists update_in_loop;{noformat}

